class Solution:
    def constructGrid(self, m, n, k):
        g = [['#'] * n for _ in range(m)]
        def count(upto, opt):
            free = lambda i, j: g[i][j] == '.' or (opt and i * n + j > upto)
            if not free(0, 0):
                return 0
            dp = [[0] * n for _ in range(m)]
            dp[0][0] = 1
            for i in range(m):
                for j in range(n):
                    if i == 0 and j == 0 or not free(i, j):
                        continue
                    dp[i][j] = (dp[i-1][j] if i else 0) + (dp[i][j-1] if j else 0)
            return dp[m-1][n-1]
        def dfs(idx):
            if idx == m * n:
                return count(m * n - 1, False) == k
            i, j = divmod(idx, n)
            for ch in '.#':
                g[i][j] = ch
                if count(idx, True) >= k and dfs(idx + 1):
                    return True
            g[i][j] = '#'
            return False
        return [''.join(r) for r in g] if dfs(0) else []

