class Solution {
    private int m, n, kk;
    private char[][] g;
    private long count(int upto, boolean opt) {
        if (g[0][0] != '.' && !(opt && 0 > upto)) return 0;
        long[][] dp = new long[m][n];
        dp[0][0] = 1;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                boolean free = g[i][j] == '.' || (opt && i * n + j > upto);
                if (!free) continue;
                dp[i][j] = (i > 0 ? dp[i-1][j] : 0) + (j > 0 ? dp[i][j-1] : 0);
            }
        return dp[m-1][n-1];
    }
    private boolean dfs(int idx) {
        if (idx == m * n) return count(m * n - 1, false) == kk;
        int i = idx / n, j = idx % n;
        for (char ch : new char[]{'.', '#'}) {
            g[i][j] = ch;
            if (count(idx, true) >= kk && dfs(idx + 1)) return true;
        }
        g[i][j] = '#';
        return false;
    }
    public String[] constructGrid(int m, int n, int k) {
        this.m = m; this.n = n; this.kk = k;
        g = new char[m][n];
        for (char[] r : g) java.util.Arrays.fill(r, '#');
        if (!dfs(0)) return new String[0];
        String[] res = new String[m];
        for (int i = 0; i < m; i++) res[i] = new String(g[i]);
        return res;
    }
}

