class Solution:
    def constructGrid(self, m, n, k):
        if m == 1 or n == 1:
            return ['.' * n] if m == 1 else (['.'] * m if k == 1 else [])
        g = [['#'] * n for _ in range(m)]
        if k == 1:
            for j in range(n): g[0][j] = '.'
            for i in range(m): g[i][n-1] = '.'
        elif n >= k:
            for j in range(n): g[0][j] = '.'
            for j in range(n - k, n): g[1][j] = '.'
            for i in range(m): g[i][n-1] = '.'
        elif m >= k:
            for i in range(m): g[i][0] = '.'
            for i in range(m - k, m): g[i][1] = '.'
            for j in range(n): g[m-1][j] = '.'
        elif m == 3 and n == 3 and k == 4:
            g = [['.'] * 3 for _ in range(3)]
            g[1][1] = '#'
        else:
            return []
        return [''.join(r) for r in g]

