public:
    vector<string> constructGrid(int m, int n, int k) {
        if (m == 1) return k == 1 ? vector<string>{string(n, '.')} : vector<string>();
        if (n == 1) return k == 1 ? vector<string>(m, ".") : vector<string>();
        vector<string> g(m, string(n, '#'));
        if (k == 1) {
            for (int j = 0; j < n; j++) g[0][j] = '.';
            for (int i = 0; i < m; i++) g[i][n-1] = '.';
        } else if (n >= k) {
            for (int j = 0; j < n; j++) g[0][j] = '.';
            for (int j = n - k; j < n; j++) g[1][j] = '.';
            for (int i = 0; i < m; i++) g[i][n-1] = '.';
        } else if (m >= k) {
            for (int i = 0; i < m; i++) g[i][0] = '.';
            for (int i = m - k; i < m; i++) g[i][1] = '.';
            for (int j = 0; j < n; j++) g[m-1][j] = '.';
        } else if (m == 3 && n == 3 && k == 4) {
            for (auto& r : g) r = string(3, '.');
            g[1][1] = '#';
